import{_ as s,o as e,c as t,a2 as p}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"山鬼","description":"","frontmatter":{"title":"山鬼","date":"2026-11-24T00:00:00.000Z","seq":10,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"屈原","source_book":"楚辞","prev":{"text":"河伯","link":"/blogs/楚辞/河伯.html"},"next":{"text":"国殇","link":"/blogs/楚辞/国殇.html"}},"headers":[],"relativePath":"blogs/楚辞/山鬼.md","filePath":"blogs/楚辞/山鬼.md"}'),o={name:"blogs/楚辞/山鬼.md"};function l(n,a,c,m,r,_){return e(),t("div",null,[...a[0]||(a[0]=[p('<h1 id="山鬼" tabindex="-1">山鬼 <a class="header-anchor" href="#山鬼" aria-label="Permalink to &quot;山鬼&quot;">​</a></h1><p class="poem-meta">先秦 · 屈原　·　九歌</p><div class="poem"><p class="poem-stanza">若有人兮山之阿，被薜荔兮带女萝</p><p class="poem-stanza">既含睇兮又宜笑，子慕予兮善窈窕</p><p class="poem-stanza">乘赤豹兮从文狸，辛夷车兮结桂旗</p><p class="poem-stanza">被石兰兮带杜衡，折芬馨兮遗所思</p><p class="poem-stanza">余处幽篁兮终不见天，路险难兮独后来</p><p class="poem-stanza">表独立兮山之上，云容容兮而在下</p><p class="poem-stanza">杳冥冥兮羌昼晦，东风飘兮神灵雨</p><p class="poem-stanza">留灵修兮憺忘归，岁既晏兮孰华予</p><p class="poem-stanza">采三秀兮于山间，石磊磊兮葛蔓蔓</p><p class="poem-stanza">怨公子兮怅忘归，君思我兮不得闲</p><p class="poem-stanza">山中人兮芳杜若，饮石泉兮荫松柏</p><p class="poem-stanza">君思我兮然疑作</p><p class="poem-stanza">雷填填兮雨冥冥，猿啾啾兮狖夜鸣</p><p class="poem-stanza">风飒飒兮木萧萧，思公子兮徒离忧。</p></div>',3)])])}const z=s(o,[["render",l]]);export{d as __pageData,z as default};
